<?php require_once '../includes/auth.php';require_login();$id=(int)($_GET['id']??0);$s=mysqli_prepare($conn,"SELECT * FROM user_files WHERE id=?");mysqli_stmt_bind_param($s,'i',$id);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);$f=mysqli_fetch_assoc($r);if(!$f)exit('Not found');$u=user();if(!is_admin() && $f['owner_id']!=$u['id'] && ($f['institution_type']!==$u['institution_type']||$f['institution_code']!==$u['institution_code']))exit('Forbidden');$path=__DIR__.'/../uploads/'.$f['stored_name'];if(!is_file($path))exit('File missing');header('Content-Type: '.$f['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.basename($f['original_name']).'"');readfile($path);
